package main

import(
"context";"crypto/tls";"github.com/eutelic/runnerhub/internal/agenthub";apihttp "github.com/eutelic/runnerhub/internal/api";"github.com/eutelic/runnerhub/internal/auth";cachepkg "github.com/eutelic/runnerhub/internal/cache";"github.com/eutelic/runnerhub/internal/core";"github.com/eutelic/runnerhub/internal/githubrunner";"github.com/eutelic/runnerhub/internal/policy";"github.com/eutelic/runnerhub/internal/reconcile";"github.com/eutelic/runnerhub/internal/scheduler";"github.com/eutelic/runnerhub/internal/store";"github.com/eutelic/runnerhub/internal/telemetry";webui "github.com/eutelic/runnerhub/web";"log";"net";"net/http";"os";"os/signal";"strconv";"strings";"syscall";"time")
var version="dev"
func main(){ctx,stop:=signal.NotifyContext(context.Background(),syscall.SIGINT,syscall.SIGTERM);defer stop();dbPath:=env("RUNNERHUB_DB","runnerhub.db");st,err:=store.OpenSQLite(dbPath);must(err);defer st.Close();enroll:=mustEnv("RUNNERHUB_ENROLLMENT_TOKEN");agentSecret:=mustEnv("RUNNERHUB_AGENT_SECRET");hub,err:=agenthub.New(st,enroll,agentSecret);must(err);metrics:=&telemetry.Metrics{};var gh githubrunner.Backend;var catalog githubrunner.Catalog;if issuer:=os.Getenv("RUNNERHUB_GITHUB_APP_ISSUER");issuer!=""{apiURL:=env("RUNNERHUB_GITHUB_API_URL","https://api.github.com");key,err:=os.ReadFile(mustEnv("RUNNERHUB_GITHUB_APP_PRIVATE_KEY_FILE"));must(err);tokens,err:=githubrunner.NewGitHubAppTokenSource(githubrunner.GitHubAppConfig{Issuer:issuer,PrivateKeyPEM:key,BaseURL:apiURL});must(err);gh,err=githubrunner.NewHTTPBackendWithBaseURL(nil,tokens,apiURL);must(err);catalog,err=githubrunner.NewHTTPCatalog(nil,tokens,apiURL);must(err)};allowed:=map[string]struct{}{};for _,x:=range strings.Split(env("RUNNERHUB_ALLOWED_IMAGES","ghcr.io/actions/actions-runner:latest"),","){if x=strings.TrimSpace(x);x!=""{allowed[x]=struct{}{}}};var cacheStore *cachepkg.Store;if root:=os.Getenv("RUNNERHUB_CACHE_DIR");root!=""{cacheStore=&cachepkg.Store{Root:root,MaxBytes:int64Env("RUNNERHUB_CACHE_MAX_OBJECT_BYTES",8<<30)}};authm:=auth.New(auth.Config{APIKeys:auth.ParseKeys(os.Getenv("RUNNERHUB_API_KEYS")),TrustOIDCHeaders:boolEnv("RUNNERHUB_TRUST_OIDC_HEADERS",false)});svc:=&apihttp.Service{Store:st,GitHub:gh,Catalog:catalog,Hub:hub,Scheduler:scheduler.Scheduler{Store:st},Policy:policy.Engine{AllowedImages:allowed,MaxResources:core.Resources{CPUMillis:64000,MemoryBytes:256<<30},RequirePinnedImages:boolEnv("RUNNERHUB_REQUIRE_PINNED_IMAGES",false),AllowPrivileged:boolEnv("RUNNERHUB_ALLOW_PRIVILEGED_WORKERS",false)},Metrics:metrics,Auth:authm,Cache:cacheStore,Static:webui.Handler()};hub.SetResultHandler(svc.HandleAgentResult);rec:=&reconcile.Reconciler{Store:st,GitHub:gh,Hub:hub,Interval:15*time.Second};go func(){if err:=rec.Run(ctx);err!=nil&&ctx.Err()==nil{log.Printf("reconciler stopped: %v",err)}}();addr:=env("RUNNERHUB_HTTP_ADDR","127.0.0.1:8080");certFile:=strings.TrimSpace(os.Getenv("RUNNERHUB_TLS_CERT_FILE"));keyFile:=strings.TrimSpace(os.Getenv("RUNNERHUB_TLS_KEY_FILE"));if (certFile=="")!=(keyFile==""){log.Fatal("RUNNERHUB_TLS_CERT_FILE and RUNNERHUB_TLS_KEY_FILE must be set together")};if certFile==""&&!isLoopbackBind(addr)&&!boolEnv("RUNNERHUB_ALLOW_INSECURE_HTTP",false){log.Fatal("non-loopback RunnerHub HTTP requires TLS; configure RUNNERHUB_TLS_CERT_FILE/RUNNERHUB_TLS_KEY_FILE or explicitly set RUNNERHUB_ALLOW_INSECURE_HTTP=true only on a separately protected network")};server:=&http.Server{Addr:addr,Handler:svc.Handler(),ReadHeaderTimeout:5*time.Second,IdleTimeout:90*time.Second,MaxHeaderBytes:1<<20,TLSConfig:&tls.Config{MinVersion:tls.VersionTLS12}};go func(){<-ctx.Done();shutdown,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();_=server.Shutdown(shutdown)}();scheme:="http";if certFile!=""{scheme="https"};log.Printf("runnerhub %s listening on %s://%s",version,scheme,addr);if certFile!=""{err=server.ListenAndServeTLS(certFile,keyFile)}else{err=server.ListenAndServe()};if err!=nil&&err!=http.ErrServerClosed{log.Fatal(err)}}
func env(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d}
func mustEnv(k string)string{v:=strings.TrimSpace(os.Getenv(k));if v==""{log.Fatalf("%s is required",k)};return v}
func boolEnv(k string,d bool)bool{v:=strings.TrimSpace(os.Getenv(k));if v==""{return d};b,err:=strconv.ParseBool(v);if err!=nil{log.Fatalf("%s must be true or false",k)};return b}
func int64Env(k string,d int64)int64{v:=strings.TrimSpace(os.Getenv(k));if v==""{return d};n,err:=strconv.ParseInt(v,10,64);if err!=nil||n<=0{log.Fatalf("%s must be a positive integer",k)};return n}
func isLoopbackBind(addr string)bool{host,_,err:=net.SplitHostPort(addr);if err!=nil{return false};if strings.EqualFold(host,"localhost"){return true};ip:=net.ParseIP(host);return ip!=nil&&ip.IsLoopback()}
func must(err error){if err!=nil{log.Fatal(err)}}
